svg.script:
(() => {
  "use strict";
  const cfg = {"name":"b06","duration":8000,"easing":"smooth","baseDrop":90.0,"verticalShare":1.0,"springMode":"removed","penMode":"extended-solid","kinematicMode":"paired-105"};
  const svg = document.documentElement;
  const wave = document.getElementById("targetWave");
  const rail = document.getElementById("movingRail");
  const hangers = document.getElementById("movingHangers");
  const carriage = document.getElementById("movingCarriage");
  const activeTip = document.getElementById("activeTip");
  const armEls = [
    [document.getElementById("arm1Outer"), document.getElementById("arm1Inner")],
    [document.getElementById("arm2Outer"), document.getElementById("arm2Inner")],
    [document.getElementById("arm3Outer"), document.getElementById("arm3Inner")],
    [document.getElementById("arm4Outer"), document.getElementById("arm4Inner")]
  ];
  const b1Els = [...document.querySelectorAll("[data-joint='b1']")];
  const b2Els = [...document.querySelectorAll("[data-joint='b2']")];
  const bConnector = document.getElementById("bConnector");
  const needles = [...document.querySelectorAll("[data-moving-needle]")];
  const LINK_GAP = 105;
  const A1 = {x:773,y:143}, A2 = {x:773,y:143+LINK_GAP};
  const B10 = {x:458,y:346}, B20 = {x:458,y:346+LINK_GAP};
  const C10 = {x:790,y:491}, C20 = {x:790,y:596};
  const tip0 = {x:867,y:702};
  const dist = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
  const lengths = {
    a1b1:dist(A1,B10), a2b2:dist(A2,B20),
    b1c1:dist(B10,C10), b2c2:dist(B20,C20),
    vertical:dist(B10,B20)
  };
  const totalWaveLength = wave.getTotalLength();
  let playing = true, progress = 0, startTime = performance.now(), raf = 0;
  let lastState = null;

  function easedTravel(p) {
    p = ((p % 1) + 1) % 1;
    const half = p <= .5 ? p * 2 : (1 - p) * 2;
    if (cfg.easing === "smooth") return half * half * (3 - 2 * half);
    if (cfg.easing === "smoother") {
      return half * half * half * (half * (half * 6 - 15) + 10);
    }
    return .5 - .5 * Math.cos(Math.PI * half);
  }

  function circleIntersection(a, c, r0, r1, reference) {
    const dx=c.x-a.x, dy=c.y-a.y, d=Math.hypot(dx,dy);
    const along=(r0*r0-r1*r1+d*d)/(2*d);
    const h=Math.sqrt(Math.max(0,r0*r0-along*along));
    const px=a.x+along*dx/d, py=a.y+along*dy/d;
    const p1={x:px-h*dy/d,y:py+h*dx/d};
    const p2={x:px+h*dy/d,y:py-h*dx/d};
    return dist(p1,reference) <= dist(p2,reference) ? p1 : p2;
  }

  function rigidTransform(s0,e0,s,e) {
    const ux=e0.x-s0.x, uy=e0.y-s0.y;
    const vx=e.x-s.x, vy=e.y-s.y;
    const lu=Math.hypot(ux,uy), lv=Math.hypot(vx,vy);
    const co=(ux*vx+uy*vy)/(lu*lv);
    const si=(ux*vy-uy*vx)/(lu*lv);
    const tx=s.x-co*s0.x+si*s0.y;
    const ty=s.y-si*s0.x-co*s0.y;
    return `matrix(${co} ${si} ${-si} ${co} ${tx} ${ty})`;
  }

  function linkedTransform(s0,e0,s,e) {
    const ux=e0.x-s0.x, uy=e0.y-s0.y;
    const vx=e.x-s.x, vy=e.y-s.y;
    const lu=Math.hypot(ux,uy), lv=Math.hypot(vx,vy);
    const u0x=ux/lu, u0y=uy/lu, n0x=-u0y, n0y=u0x;
    const u1x=vx/lv, u1y=vy/lv, n1x=-u1y, n1y=u1x;
    const axialScale=lv/lu;
    const aa=n1x*n0x+axialScale*u1x*u0x;
    const bb=n1y*n0x+axialScale*u1y*u0x;
    const cc=n1x*n0y+axialScale*u1x*u0y;
    const dd=n1y*n0y+axialScale*u1y*u0y;
    const tx=s.x-aa*s0.x-cc*s0.y;
    const ty=s.y-bb*s0.x-dd*s0.y;
    return `matrix(${aa} ${bb} ${cc} ${dd} ${tx} ${ty})`;
  }

  function placeJoint(elements, p) {
    elements.forEach(el => { el.setAttribute("cx",p.x); el.setAttribute("cy",p.y); });
  }

  function applyFrame(p) {
    progress = Math.max(0,Math.min(1,Number(p)||0));
    const travel = easedTravel(progress);
    const target = wave.getPointAtLength(totalWaveLength * travel);
    const dx = target.x-tip0.x;
    const totalDy = target.y-tip0.y;
    const railDy = totalDy;
    const extension = 0;
    const c1={x:C10.x+dx,y:C10.y+railDy};
    const c2={x:C20.x+dx,y:C20.y+railDy};
    const b1=circleIntersection(A1,c1,lengths.a1b1,lengths.b1c1,B10);
    const b2={x:b1.x,y:b1.y+LINK_GAP};
    const assembly=`translate(${dx} ${railDy})`;
    rail.setAttribute("transform",assembly);
    hangers.setAttribute("transform",assembly);
    carriage.setAttribute("transform",assembly);

    needles.forEach(el => {
      const x=Number(el.dataset.x), y=Number(el.dataset.y);
      el.setAttribute("transform",`translate(${x} ${y+extension})`);
    });

    const armTransforms=[
      rigidTransform(A1,B10,A1,b1),
      rigidTransform(A2,B20,A2,b2),
      rigidTransform(B10,C10,b1,c1),
      rigidTransform(B20,C20,b2,c2)
    ];
    armEls.forEach((pair,i)=>pair.forEach(el=>el.setAttribute("transform",armTransforms[i])));
    placeJoint(b1Els,b1); placeJoint(b2Els,b2);
    bConnector.setAttribute("transform",linkedTransform(B10,B20,b1,b2));

    const tip={x:tip0.x+dx,y:tip0.y+railDy+extension};
    const current=[dist(A1,b1),dist(A2,b2),dist(b1,c1),dist(b2,c2)];
    const original=[lengths.a1b1,lengths.a2b2,lengths.b1c1,lengths.b2c2];
    const maxBarDrift=Math.max(...current.map((n,i)=>Math.abs(n/original[i]-1)));
    lastState={
      progress, travel, target:{x:target.x,y:target.y}, tip, dx, railDy, extension,
      A1:{...A1},A2:{...A2},b1,b2,c1,c2,
      tipDistance:dist(tip,target),
      maxBarDrift,
      verticalLinkDrift:Math.abs(dist(b1,b2)/lengths.vertical-1),
      fixedPivotDrift:0,
      railCarriageRelativeDrift:0,
      finite:[target.x,target.y,tip.x,tip.y,b1.x,b1.y,b2.x,b2.y,c1.x,c1.y,c2.x,c2.y]
        .every(Number.isFinite)
    };
    svg.dataset.progress=progress.toFixed(6);
    return lastState;
  }

  function tick(now) {
    if (!playing) return;
    progress=((now-startTime)%cfg.duration)/cfg.duration;
    applyFrame(progress);
    raf=requestAnimationFrame(tick);
  }
  function pause() { playing=false; cancelAnimationFrame(raf); return progress; }
  function play() {
    if (!playing) {
      playing=true;
      startTime=performance.now()-progress*cfg.duration;
      raf=requestAnimationFrame(tick);
    }
    return progress;
  }
  function seek(p) { pause(); return applyFrame(p); }
  function metrics() {
    return {
      ...lastState,
      config:{...cfg},
      barLengths:{...lengths},
      playing,
      apiVersion:1
    };
  }
  window.__pantograph={seek,pause,play,metrics};
  applyFrame(0);
  raf=requestAnimationFrame(tick);
})();
